-- 伦理独立流程（申请、受理、委员意见、决定、持续审查/修正案/不良事件）
--
-- 本文件作为有序迁移执行。没有执行本迁移时，EthicsController 的写入接口会因表不存在
-- 而失败，避免把空数据误报为真实伦理审查结果。
BEGIN;

-- 独立流程需要将批准结果回写到纵向项目；若 070 已先执行，IF NOT EXISTS 保持幂等。
ALTER TABLE "纵向项目立项"
    ADD COLUMN IF NOT EXISTS "伦理批文有效期至" date NULL,
    ADD COLUMN IF NOT EXISTS "伦理审查状态" varchar(50) DEFAULT '无需伦理';

CREATE TABLE IF NOT EXISTS "伦理审查申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "申请类型" varchar(30) NOT NULL DEFAULT '初始审查',
    "申请标题" varchar(200) NOT NULL,
    "研究方案摘要" text NOT NULL,
    "受试者风险等级" varchar(20) NOT NULL DEFAULT '一般风险',
    "知情同意说明" text,
    "附件路径" text,
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "提交时间" timestamp without time zone,
    "受理时间" timestamp without time zone,
    "决定时间" timestamp without time zone,
    "批件编号" varchar(100),
    "有效期至" date,
    "批件路径" text,
    "退回原因" varchar(2000),
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_伦理申请_类型" CHECK ("申请类型" IN ('初始审查','修正案','年度跟踪审查','延期续展')),
    CONSTRAINT "ck_伦理申请_风险" CHECK ("受试者风险等级" IN ('低风险','一般风险','高风险')),
    CONSTRAINT "ck_伦理申请_状态" CHECK ("状态" IN ('草稿','待受理','审查中','需补正','已批准','已拒绝','已撤回')),
    CONSTRAINT "ck_伦理申请_日期" CHECK ("有效期至" IS NULL OR "决定时间" IS NULL OR "有效期至" >= "决定时间"::date)
);
CREATE INDEX IF NOT EXISTS "ix_伦理申请_项目状态" ON "伦理审查申请" ("流程模板编号","项目编号","状态");
CREATE INDEX IF NOT EXISTS "ix_伦理申请_状态有效期" ON "伦理审查申请" ("状态","有效期至");
CREATE INDEX IF NOT EXISTS "ix_伦理申请_申请人" ON "伦理审查申请" ("申请人编号","建立时间" DESC);

CREATE TABLE IF NOT EXISTS "伦理审查会议" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "会议序号" varchar(50) NOT NULL,
    "会议时间" timestamp without time zone NOT NULL,
    "会议地点" varchar(200),
    "主持人编号" integer REFERENCES "人员"("编号"),
    "状态" varchar(20) NOT NULL DEFAULT '计划中',
    "议程路径" text,
    "会议纪要路径" text,
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_伦理会议_序号" UNIQUE ("会议序号"),
    CONSTRAINT "ck_伦理会议_状态" CHECK ("状态" IN ('计划中','进行中','已完成','已取消'))
);

CREATE TABLE IF NOT EXISTS "伦理审查委员意见" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "申请编号" bigint NOT NULL REFERENCES "伦理审查申请"("编号") ON DELETE CASCADE,
    "会议编号" bigint REFERENCES "伦理审查会议"("编号"),
    "委员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "是否利益冲突" boolean NOT NULL DEFAULT false,
    "意见结论" varchar(20) NOT NULL,
    "意见内容" text,
    "评分" numeric(5,2),
    "提交时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_伦理委员意见" UNIQUE ("申请编号","委员编号"),
    CONSTRAINT "ck_伦理委员意见_结论" CHECK ("意见结论" IN ('同意','修改后同意','不同意','回避')),
    CONSTRAINT "ck_伦理委员意见_评分" CHECK ("评分" IS NULL OR ("评分" >= 0 AND "评分" <= 100)),
    CONSTRAINT "ck_伦理委员意见_冲突" CHECK (NOT "是否利益冲突" OR "意见结论" = '回避')
);

CREATE TABLE IF NOT EXISTS "伦理审查决定" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "申请编号" bigint NOT NULL REFERENCES "伦理审查申请"("编号") ON DELETE CASCADE,
    "决定" varchar(20) NOT NULL,
    "决定说明" varchar(4000) NOT NULL,
    "批件编号" varchar(100),
    "批准时间" timestamp without time zone,
    "有效期至" date,
    "决定书路径" text,
    "决定人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_伦理决定_结果" CHECK ("决定" IN ('批准','修改后批准','补正后再审','拒绝','终止')),
    CONSTRAINT "ck_伦理决定_批准信息" CHECK (("决定" IN ('批准','修改后批准') AND "批件编号" IS NOT NULL AND "有效期至" IS NOT NULL) OR "决定" NOT IN ('批准','修改后批准'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_伦理决定_当前申请" ON "伦理审查决定" ("申请编号") WHERE "决定" NOT IN ('补正后再审');

CREATE TABLE IF NOT EXISTS "伦理持续审查记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "申请编号" bigint NOT NULL REFERENCES "伦理审查申请"("编号") ON DELETE CASCADE,
    "记录类型" varchar(30) NOT NULL,
    "发生日期" date,
    "下次审查日期" date,
    "严重程度" varchar(20),
    "事件说明" text NOT NULL,
    "处理结论" varchar(2000),
    "附件路径" text,
    "状态" varchar(20) NOT NULL DEFAULT '待审查',
    "提交人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_伦理持续_类型" CHECK ("记录类型" IN ('年度跟踪审查','方案修正案','知情同意修订','不良事件','偏离方案')),
    CONSTRAINT "ck_伦理持续_严重程度" CHECK ("严重程度" IS NULL OR "严重程度" IN ('一般','严重','危及生命')),
    CONSTRAINT "ck_伦理持续_状态" CHECK ("状态" IN ('待审查','审查中','已批准','需补正','已关闭'))
);
CREATE INDEX IF NOT EXISTS "ix_伦理持续_申请日期" ON "伦理持续审查记录" ("申请编号","记录类型","状态","下次审查日期");

COMMENT ON TABLE "伦理审查申请" IS '科研伦理独立审查申请主表，真实结果由委员会决定后登记';
COMMENT ON TABLE "伦理持续审查记录" IS '年度跟踪、修正案、不良事件和方案偏离的统一持续审查记录';

-- 菜单入口沿用现有科研办公父菜单；现代前端通过 route-resolver 接管该路径。
INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (806, 1, '科研伦理审查', '科研办公/科研办公/科研伦理审查.html', TRUE, '伦理申请、委员会决定和持续审查记录')
ON CONFLICT ("编号") DO UPDATE
SET "上级编号" = EXCLUDED."上级编号", "名称" = EXCLUDED."名称", "路径" = EXCLUDED."路径",
    "类型" = EXCLUDED."类型", "备注" = EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 806 FROM "角色" r
 WHERE r."名称" IN ('系统管理员','科研管理员','科技办','科研科负责人','科研处处长','伦理秘书','伦理委员会秘书','伦理委员','伦理委员会委员')
   AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=806);

UPDATE "系统迁移版本"
   SET "版本" = 74,
       "脚本" = '074_ethics_review_workflow.sql',
       "检查摘要" = '新增伦理审查申请、会议、委员意见、决定和持续审查记录',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
